package com.familyguard.parent;

import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.view.ViewGroup;import android.widget.*;
import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;import org.webrtc.*;import java.util.*;

/** Parent receiver for a Child-approved live camera session. */
public class LiveCameraActivity extends Activity{
 private SurfaceViewRenderer renderer;private VideoTrack displayedTrack;private EglBase egl;private TextView status;private Button start,stop;private String childUid,parentUid,sessionId;private DocumentReference ref;private PeerConnectionFactory factory;private PeerConnection peer;private ListenerRegistration sessionListener,candidateListener;private final List<IceCandidate> localPending=new ArrayList<>(),remotePending=new ArrayList<>();private final Set<String> seen=new HashSet<>();private boolean created=false,answerSet=false,ending=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);childUid=getIntent().getStringExtra("childUid");parentUid=FirebaseAuth.getInstance().getUid();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,24,20,20);root.setBackgroundColor(Color.BLACK);TextView h=new TextView(this);h.setTextColor(Color.WHITE);h.setTextSize(21);h.setText("FamilyGuard — Live camera");status=new TextView(this);status.setTextColor(Color.WHITE);status.setText("Camera is off. Child approval and Android CAMERA permission are required.");renderer=new SurfaceViewRenderer(this);renderer.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));start=new Button(this);start.setText("Request live camera");start.setOnClickListener(v->request());stop=new Button(this);stop.setText("Stop / cancel camera");stop.setEnabled(false);stop.setOnClickListener(v->end());root.addView(h);root.addView(status);root.addView(renderer);root.addView(start);root.addView(stop);setContentView(root);if(childUid==null||parentUid==null){status.setText("Missing Parent or Child account.");start.setEnabled(false);}}
 private void request(){if(peer!=null)return;ending=false;created=false;answerSet=false;seen.clear();localPending.clear();remotePending.clear();start.setEnabled(false);stop.setEnabled(true);status.setText("Request sent after connection setup; waiting for Child approval.");try{PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions.builder(getApplicationContext()).createInitializationOptions());egl=EglBase.create();renderer.init(egl.getEglBaseContext(),null);renderer.setEnableHardwareScaler(true);renderer.setMirror(false);factory=PeerConnectionFactory.builder().setVideoEncoderFactory(new DefaultVideoEncoderFactory(egl.getEglBaseContext(),true,true)).setVideoDecoderFactory(new DefaultVideoDecoderFactory(egl.getEglBaseContext())).createPeerConnectionFactory();PeerConnection.RTCConfiguration cfg=new PeerConnection.RTCConfiguration(Collections.singletonList(PeerConnection.IceServer.builder("stun:stun.l.google.com:19302").createIceServer()));cfg.sdpSemantics=PeerConnection.SdpSemantics.UNIFIED_PLAN;peer=factory.createPeerConnection(cfg,new PeerConnection.Observer(){
 public void onSignalingChange(PeerConnection.SignalingState s){}public void onIceConnectionChange(PeerConnection.IceConnectionState s){runOnUiThread(()->status.setText("Camera connection: "+s));if(s==PeerConnection.IceConnectionState.FAILED)fail("Connection failed; a TURN relay may be required.");}public void onStandardizedIceConnectionChange(PeerConnection.IceConnectionState s){}public void onConnectionChange(PeerConnection.PeerConnectionState s){}public void onIceConnectionReceivingChange(boolean b){}public void onIceGatheringChange(PeerConnection.IceGatheringState s){}public void onIceCandidate(IceCandidate c){if(created)writeCandidate(c);else localPending.add(c);}public void onIceCandidatesRemoved(IceCandidate[] c){}public void onAddStream(MediaStream s){if(!s.videoTracks.isEmpty())show(s.videoTracks.get(0));}public void onRemoveStream(MediaStream s){}public void onDataChannel(DataChannel c){}public void onRenegotiationNeeded(){}public void onAddTrack(RtpReceiver r,MediaStream[] s){if(r.track() instanceof VideoTrack)show((VideoTrack)r.track());}public void onTrack(RtpTransceiver t){if(t.getReceiver().track() instanceof VideoTrack)show((VideoTrack)t.getReceiver().track());}});
 peer.addTransceiver(MediaStreamTrack.MediaType.MEDIA_TYPE_VIDEO,new RtpTransceiver.RtpTransceiverInit(RtpTransceiver.RtpTransceiverDirection.RECV_ONLY));ref=FirebaseFirestore.getInstance().collection("cameraSessions").document();sessionId=ref.getId();peer.createOffer(new SdpObserverAdapter(){public void onCreateSuccess(SessionDescription offer){peer.setLocalDescription(new SdpObserverAdapter(){public void onSetSuccess(){Map<String,Object>o=new HashMap<>();o.put("type",offer.type.canonicalForm());o.put("sdp",offer.description);Map<String,Object>d=new HashMap<>();d.put("parentUid",parentUid);d.put("childUid",childUid);d.put("status","requested");d.put("createdAt",FieldValue.serverTimestamp());d.put("offer",o);ref.set(d).addOnSuccessListener(v->{created=true;for(IceCandidate c:new ArrayList<>(localPending))writeCandidate(c);localPending.clear();listen();status.setText("Request sent. Child must approve and grant camera permission.");}).addOnFailureListener(e->fail("Could not send request: "+e.getMessage()));}},offer);}public void onCreateFailure(String e){fail("Offer failed: "+e);}},new MediaConstraints());}catch(Exception e){fail("Camera WebRTC setup failed: "+e.getMessage());}}
 private void listen(){sessionListener=ref.addSnapshotListener((s,e)->{if(e!=null||s==null||!s.exists()){fail("Camera session unavailable.");return;}String state=s.getString("status");if("denied".equals(state)){ending=true;cleanup();status.setText("Child denied camera access.");return;}if("ended".equals(state)||"cancelled".equals(state)){ending=true;cleanup();status.setText("Live camera ended.");return;}Object a=s.get("answer");if("approved".equals(state)&&a instanceof Map&&!answerSet){Map<String,Object>m=(Map<String,Object>)a;peer.setRemoteDescription(new SdpObserverAdapter(){public void onSetSuccess(){answerSet=true;for(IceCandidate c:new ArrayList<>(remotePending))peer.addIceCandidate(c);remotePending.clear();status.setText("Receiving Child-approved live camera.");}public void onSetFailure(String e){fail("Invalid camera answer: "+e);}},new SessionDescription(SessionDescription.Type.fromCanonicalForm(String.valueOf(m.get("type"))),String.valueOf(m.get("sdp"))));}});candidateListener=ref.collection("candidates").addSnapshotListener((s,e)->{if(e!=null||s==null||peer==null)return;for(DocumentSnapshot d:s.getDocuments())if(!parentUid.equals(d.getString("senderUid"))&&seen.add(d.getId()))try{org.json.JSONObject j=new org.json.JSONObject(d.getString("candidate"));IceCandidate c=new IceCandidate(j.optString("sdpMid"),j.optInt("sdpMLineIndex"),j.getString("sdp"));if(answerSet)peer.addIceCandidate(c);else remotePending.add(c);}catch(Exception ignored){}});}
 private void show(VideoTrack t){runOnUiThread(()->{if(renderer!=null&&displayedTrack!=t){if(displayedTrack!=null)displayedTrack.removeSink(renderer);displayedTrack=t;t.addSink(renderer);status.setText("Receiving Child-approved live camera video.");}});}
 private void writeCandidate(IceCandidate c){try{Map<String,Object>d=new HashMap<>();d.put("senderUid",parentUid);d.put("candidate",new org.json.JSONObject().put("sdpMid",c.sdpMid).put("sdpMLineIndex",c.sdpMLineIndex).put("sdp",c.sdp).toString());d.put("createdAt",FieldValue.serverTimestamp());ref.collection("candidates").add(d);}catch(Exception ignored){}}
 private void end(){ending=true;if(ref!=null)ref.update("status","cancelled","updatedAt",FieldValue.serverTimestamp());cleanup();status.setText("Camera session stopped.");start.setEnabled(true);stop.setEnabled(false);}
 private void fail(String m){runOnUiThread(()->{status.setText(m);if(ref!=null)ref.update("status","cancelled","updatedAt",FieldValue.serverTimestamp());ending=true;cleanup();start.setEnabled(true);stop.setEnabled(false);});}
 private void cleanup(){if(displayedTrack!=null&&renderer!=null){try{displayedTrack.removeSink(renderer);}catch(Exception ignored){}displayedTrack=null;}if(sessionListener!=null){sessionListener.remove();sessionListener=null;}if(candidateListener!=null){candidateListener.remove();candidateListener=null;}try{if(peer!=null){peer.close();peer.dispose();peer=null;}}catch(Exception ignored){}try{if(factory!=null){factory.dispose();factory=null;}}catch(Exception ignored){}try{if(renderer!=null)renderer.release();}catch(Exception ignored){}try{if(egl!=null){egl.release();egl=null;}}catch(Exception ignored){}if(!ending&&ref!=null)ref.update("status","cancelled","updatedAt",FieldValue.serverTimestamp());}
 @Override public void onDestroy(){if(!ending&&ref!=null)ref.update("status","cancelled","updatedAt",FieldValue.serverTimestamp());ending=true;cleanup();super.onDestroy();}
 static class SdpObserverAdapter implements SdpObserver{public void onCreateSuccess(SessionDescription s){}public void onSetSuccess(){}public void onCreateFailure(String e){}public void onSetFailure(String e){}}
}